component.componentCode:
"use client"

// AsciiArt — "HANZO CCTV Binary", made with the 21st ASCII editor and baked
// to its exact rendered output (looping video + poster). Zero dependencies:
// one <video> that fills its parent. Drop it behind or inside your content:
// <div className="relative h-96"><AsciiArt className="absolute inset-0" /></div>
// Remix the source recipe (styles, animation, palette) in the editor:
// https://21st.dev/community/ascii/editor?from=9ec4a5d6-2869-44d7-8484-ab209c6433bd
export function AsciiArt({ className }: { className?: string }) {
  return (
    <video
      className={className}
      src={"https://assets.21st.dev/ascii-recipes/videos/user_3GPGUGW0kezwI1M261bFhugwynL/e45ee2a7-81d0-4689-a9f5-957b0790aae3.mp4"}
      poster={"https://assets.21st.dev/ascii-recipes/thumbnails/user_3GPGUGW0kezwI1M261bFhugwynL/1a06199c-ea44-40fe-af05-cdaf297fe111.webp"}
      autoPlay
      loop
      muted
      playsInline
      aria-label={"HANZO CCTV Binary — animated ASCII art"}
      style={{
        display: "block",
        width: "100%",
        height: "100%",
        objectFit: "cover",
      }}
    />
  )
}

